    'blocchi.questaPersona': 'Questa persona',
    'blocchi.membroIntoccabile': (chi, azione, quanti, elenco) => `${chi}: ${azione} non è possibile.\n\n`
      + `Ha presenze in ${quanti === 1 ? 'un giorno con le presenze bloccate' : `${quanti} giorni con le presenze bloccate`} `
      + `(${elenco}). Cambiarla adesso riscriverebbe le quote di quei giorni, `
      + 'che invece devono restare come sono.\n\n'
      + 'Se serve davvero, prima sblocca quei giorni dalla scheda Presenze.',
    'blocchi.avvisoSblocco': (quanti, elenco) => `\n\nATTENZIONE: ${quanti === 1 ? 'un giorno con le presenze bloccate' : `${quanti} giorni con le presenze bloccate`} `
      + `(${elenco}) ${quanti === 1 ? 'verrà sbloccato o cambiato' : 'verranno sbloccati o cambiati'}. `
      + 'Le quote di quei giorni possono cambiare.',
    'blocchi.giornoIntoccabile': (giorno, azione) => `${giorno}: ${azione} non è possibile.\n\n`
      + 'Le presenze di questo giorno sono bloccate, e questo interruttore ne cambierebbe le quote.\n\n'
      + 'Se serve davvero: sblocca il giorno qui in Presenze, cambia, e ribloccalo.',
    'gratis.azione': 'cambiare "giorno gratis"',
    'gratis.confermaRimetti': (giorno) => `Rimettere ${giorno} nei conti?\n\n`
      + 'I pasti di quel giorno tornano a contare nelle quote di tutti.',
    'gratis.confermaRendi': (giorno, quanti) => `Rendere ${giorno} gratis per tutti?\n\n`
      + `I pasti di quel giorno (${quanti} ${quanti === 1 ? 'persona' : 'persone'}) restano segnati per la cucina, `
      + 'ma escono da TUTTI i conti: nessuno li paga, e chi è venuto solo quel giorno non deve niente.\n\n'
      + 'Attenzione: la spesa già registrata non sparisce. Se hai comprato del cibo per quel giorno, '
      + 'quel costo si divide sugli altri giorni e le quote degli altri salgono. Serve quando quel '
      + 'giorno lo ha offerto qualcuno o si è mangiato fuori a spese proprie.',
    'blocchi.confermaBlocca': (giorno, quanti) => `Bloccare le presenze di ${giorno}?\n\n`
      + `Restano congelate così come sono adesso (${quanti} ${quanti === 1 ? 'persona' : 'persone'} con almeno un pasto). `
      + 'Da quel momento non si toccano più: né dai tasti, né da quello che arriva dagli altri telefoni.\n\n'
      + 'Si può sbloccare da qui, in modalità tecnica.',
    'blocchi.confermaSblocca': (giorno) => `Sbloccare le presenze di ${giorno}?\n\n`
      + 'Tornano modificabili da tutti, e riprendono a sincronizzarsi.',
    'chiusura.confermaChiudi': (quante, soldi, aperti) => 'Chiudere i conti del campo?\n\n'
      + `Spese e attrezzatura si congelano (${quante} spese, ${soldi} €), `
      + `e le presenze dei giorni ancora aperti vengono bloccate (${aperti}).\n\n`
      + 'Da quel momento gli importi di "chi paga chi" non cambiano più, così i rimborsi già '
      + 'segnati come saldati restano validi. Quello che arriva dopo dagli altri telefoni viene '
      + 'messo da parte e te lo si dice.\n\n'
      + 'Si può riaprire da qui, in modalità tecnica.',
    'chiusura.confermaRiapri': 'Riaprire i conti?\n\n'
      + 'Spese e attrezzatura tornano modificabili, e gli importi di "chi paga chi" '
      + 'si ricalcolano: i rimborsi già segnati come saldati potrebbero non combaciare più.\n\n'
      + 'Le presenze restano bloccate: si sbloccano una per una dalla scheda Presenze.',
    'chiusura.azioneImpossibile': (azione) => `I conti del campo sono chiusi: ${azione} non è possibile.\n\n`
      + 'Serve per non far cambiare gli importi dei rimborsi già in corso. '
      + 'Per modificare, riapri i conti da Spese Totali → Dati (modalità tecnica).',
    'orfane.scegliChi': 'Scegli a chi assegnarle.',
    'orfane.di': (nome) => `di ${nome}`,
    'orfane.senzaPadrone': 'senza padrone',
    'orfane.confermaAssegna': (dest, pasti, chi, giorni) => `Assegnare a ${dest} le ${pasti} presenze ${chi}?\n\n`
      + `Riguardano ${giorni} ${giorni === 1 ? 'giorno' : 'giorni'}. `
      + 'Se in quei giorni ha già dei pasti segnati, si sommano (non si perde niente).',
    'orfane.confermaButta': (pasti, chi, protetti) => `Buttare via le ${pasti} presenze ${chi}?\nNon si potranno recuperare.`
      + (protetti ? `\n\nQuelle dei giorni bloccati (${protetti}) restano dove sono: `
        + 'per toglierle bisogna prima sbloccare quei giorni.' : ''),
    'membri.confermaUnisci': (nome, volte, pasti) => `"${nome}" è in elenco ${volte} volte.\n\n`
      + 'Succede quando due telefoni senza linea aggiungono la stessa persona: '
      + 'per i conti diventano due persone diverse, e la quota sbaglia per tutti.\n\n'
      + `Unendole resta una scheda sola${pasti ? `, e le ${pasti} presenze segnate sull'altra si sommano a queste` : ''}. `
      + 'Non si perde niente.',
    'spesa.prezzoAlto': (soldi, mediana) => `${soldi} € è una cifra alta.\n\n`
      + (mediana ? `Le altre spese del campo stanno intorno a ${mediana} €: questa è più di dieci volte tanto.`
        : 'Controlla che non ci sia una virgola fuori posto.')
      + '\n\nUna cifra sbagliata qui si spalma sulle quote di tutti e non si nota più.\n\nÈ giusta?',
    'presenze.confermaTogli': (pasto, quanti, giorno) => `Togliere il ${pasto} a tutti e ${quanti} i membri di ${giorno}?`,
    'presenze.confermaSegna': (quanti, pasto, giorno) => `Segnare tutti e ${quanti} i membri a ${pasto} di ${giorno}?`,
    'presenze.cambiaPerTutti': (testo) => `${testo}\n\nCambia le presenze di tutti, anche sugli altri telefoni.`,
    'presenze.bloccateSblocca': (giorno) => `Le presenze di ${giorno} sono bloccate: prima vanno sbloccate.`,
    'presenze.nessunaIeri': 'Nessuna presenza registrata il giorno precedente.',
    'presenze.confermaCopia': (ieri, oggi, ieriPranzo, ieriCena, oggiPranzo, oggiCena) => `Copiare le presenze di ${ieri} su ${oggi}?\n\n`
      + `Ieri: ${ieriPranzo} a pranzo, ${ieriCena} a cena.\n`
      + `Oggi diventa uguale: quello che c'è adesso (${oggiPranzo} a pranzo, ${oggiCena} a cena) viene sostituito, `
      + 'anche sugli altri telefoni.',
    'membri.confermaOmonimo': (nome) => `C'è già un membro che si chiama "${nome}".\n\n`
      + 'Nei conti finali le due persone verrebbero confuse. Aggiungi un cognome '
      + 'o un soprannome per distinguerle.\n\nVuoi aggiungerlo lo stesso?',
    'membri.confermaElimina': (nome) => `Eliminare ${nome} dai membri?\nLe sue presenze e i suoi pasti non conteranno più nei calcoli.`,
    // Perche' dei soldi non finiscono nelle quote di nessuno. conti.js e' puro
