    'buchi.separatoSenzaGiorni': 'spese segnate "conto separato", ma in Calendario nessun giorno è spuntato come separato',
    'buchi.separatoTuttiGratis': 'spese segnate "conto separato", ma i giorni separati sono anche segnati come gratis: non c\'è più nessun pasto su cui dividerle',
    'buchi.separatoSenzaPresenze': 'spese segnate "conto separato", ma nei giorni separati non c\'è nessuna presenza',
    'buchi.logistica': 'spese di logistica, ma nessuno che paga ha presenze nei giorni comuni',
    'buchi.attrezzatura': 'attrezzatura acquistata, ma nessuno che paga ha presenze nei giorni comuni',
