    'fraAlcuni.nessuno': 'Hai scelto «solo alcuni», ma nessun nome: tocca chi divide questa spesa.',
    'fraAlcuni.etichetta': (n) => `fra ${n}`,
    'fraAlcuni.titolo': 'Spese fra alcuni',
    'fraAlcuni.spiega': 'Divise in parti uguali solo fra chi le ha scelte, fuori dalle quote per pasto. Chi le ha pagate le riceve nei Saldi, con il resto della cassa comune.',
    'fraAlcuni.pagataDa': (chi) => `pagata da ${chi}`,
    'spesa.fraAlcuni': 'Fra alcuni',
    'buchi.fraAlcuniSenzaNessuno': 'spese da dividere fra alcuni, ma nessuno di loro è più fra i membri',
