    'report.totale': (soldi) => `💶 Totale spese: ${soldi} €`,
    'report.diCuiSeparato': (soldi, giorni, aPasto) => `   di cui conto separato: ${soldi} € su ${giorni} ${giorni === 1 ? 'giorno' : 'giorni'} (${aPasto} € a pasto)`,
    'report.chiPagaChi': (titolo) => `👉 Chi paga chi${titolo ? ` — ${titolo}` : ''}:`,
    'report.riga': (da, a, soldi) => `• ${da} → ${a}: ${soldi} €`,
    'report.giaFatti': (titolo) => `✅ Già fatti${titolo ? ` — ${titolo}` : ''}:`,
    'report.rigaFatta': (da, a, soldi) => `• ${da} → ${a}: ${soldi} € ✓`,
    'report.tuttiFatti': 'Tutti i rimborsi sono fatti.',
    'report.dettaglio': (titolo) => `📋 Dettaglio a testa${titolo ? ` — ${titolo}` : ''}:`,
    'report.riceve': (soldi) => `riceve ${soldi} €`,
