    'report.buco': (soldi, perche) => `   • ${soldi} € — ${perche}`,
    'report.scoperto': '   Chi ha anticipato quella cifra resta scoperto: da sistemare prima di pagare.',
    'report.nienteDaCondividere': 'Nessuna spesa da condividere: registra prima gli acquisti.',
