    'lista.doppia': (nome, prezzo, volte, chi) => `*"${nome}" de ${prezzo} € está registrado ${volte} veces*${chi ? ` (por ${chi})` : ''}. Si es el mismo gasto puesto por dos personas, el total está inflado y la cuota de todos sube: borra uno aquí abajo con la *×*. Si de verdad son dos gastos distintos, déjalo — o cambia un nombre para no volver a caer.`,
    'lista.nessunAcquisto': 'Ninguna compra registrada. Rellena el formulario de aquí arriba y pulsa Guardar.',
