    'avviso.hoCapito': 'Entendido',
    'respinte.testa': (quanti) => `*Las cuentas están cerradas: ${quanti} ${quanti === 1 ? 'cambio ha sido rechazado' : 'cambios han sido rechazados'}.*`,
    'respinte.riga': (che, nome, azione, soldi) => `${che} "${nome}" ${azione} (${soldi} €)`,
    'respinte.altre': (quante) => ` …y otros ${quante}`,
    'respinte.coda': 'Si hay que aceptarlos, reabre las cuentas desde *Gastos totales → Datos* y vuelve a hacerlos.',
    'azione.aggiunta': 'añadida',
    'azione.modificata': 'modificada',
    'azione.cancellata': 'borrada',
    'orologio.avviso': (giorni) => `*Un teléfono tiene el reloj adelantado ${giorni} días.* Sus cambios ganan a todos los demás incluso cuando son más viejos, y las correcciones hechas por los otros se descartan sin avisar. Preguntad quién tiene la fecha mal y que la arregle (o a lo mejor es este teléfono el que va atrasado).`,
    'orologio.sistemato': 'Arreglado',
    'perdita.avviso': (quante, quando, che) => `*Alguien acaba de borrar ${quante} entradas${quando ? ` (${quando})` : ''}.*${che ? ` ${che}.` : ''} Si no ha sido ninguno de vosotros, deshazlo: vuelve todo como estaba, en todos los teléfonos.`,
