    'correggi.notaLogistica': 'La *logística* se divide por cabeza entre quienes tienen comidas en los días de cuenta común, no por día: quien estuvo solo en los días de cuenta aparte no la paga, y por eso aquí la cuenta no se aplica.',
    'ripristino.titolo': 'Restaurar una copia',
    'ripristino.nota': 'Copias automáticas: dos al día en el teléfono (una después de medianoche y otra después de mediodía, en la primera apertura), más una al día en la nube. Las que están *en el teléfono* están también sin conexión.',
