    'guida.campo.titolo': "Le camp et l'invitation",
    'guida.campo.corpo': "Chaque camp a un code de huit caractères : qui l'a entre, même sans compte. Depuis « Le camp » (dans le menu) tu l'envoies avec le bouton Partager, ou tu copies le lien. Celui qui a créé le camp est le chef de groupe : de là il change le nom et les dates, choisit le lieu pour la météo, décide ce qui se partage, nomme un second chef de groupe et écrit les règles et quoi apporter. Les autres voient les mêmes choses, sans pouvoir les modifier.",
