    'menu.aggiungiN': (n) => `Ajouter (${n})`,
    'menu.giorniDelCampo': 'Jours du camp',
    'menu.daScrivere': 'à écrire',
    'presenze.orfaneTitolo': (totale) => `*Il y a ${totale} présences sans propriétaire.* Ça arrive quand une personne est supprimée des Membres puis rajoutée : pour l'application c'est une nouvelle personne, et les repas notés avant restent accrochés à l'ancienne — disparus de la liste et des comptes. Rends-les à la bonne personne.`,
    'presenze.personaSparita': 'Personne qui ne figure plus dans la liste',
    'presenze.pastiSuGiorni': (pasti, giorni) => `${pasti} ${pasti < 2 ? 'repas' : 'repas'} sur ${giorni} ${giorni < 2 ? 'jour' : 'jours'}`,
    'presenze.aChiSono': '— à qui sont-elles ? —',
    'presenze.riassegna': 'Réattribuer',
    'presenze.buttaVia': 'Jeter ces présences',
    'presenze.butta': 'Jeter',
    'presenze.delGiorno': (data) => `Présences du ${data}`,
    'presenze.bloccate': '🔒 Bloquées',
    'presenze.gratis': "*🎁 Journée offerte.* Les présences restent notées pour la cuisine, mais n'entrent dans aucun compte : personne ne paie les repas d'aujourd'hui, et qui n'est venu qu'aujourd'hui ne doit rien.",
    'presenze.gratisTogli': '🎁 Journée offerte — remets-la dans les comptes',
    'presenze.gratisMetti': '🎁 Rendre cette journée gratuite',
    'presenze.chiuse': (quando) => `*Présences closes.* Elles ont été bloquées le ${quando} et ne changent plus : ni par les boutons, ni par ce qui arrive des autres téléphones. Si un téléphone essaie de les modifier, l'application les remet comme elles étaient.`,
    'presenze.primaIMembri': 'Ajoute d\'abord les membres dans l\'onglet « Membres ».',
    'presenze.segnaInBlocco': 'Noter en bloc',
    'presenze.pranzoCena': (pranzo, cena) => `${pranzo} à midi · ${cena} le soir`,
    'presenze.tuttiPranzo': 'Tous à midi',
    'presenze.tuttiCena': 'Tous le soir',
    'presenze.copiaIeri': 'Copier sur hier',
    'presenze.tuttiSempre': 'Tout le monde, à chaque repas, tout le camp',
    'presenze.avvioVeloce': "Aucun repas marqué pour l'instant. *Vous êtes toujours tous là ?* Marque tout le monde d'un geste, puis retire seulement qui manque.",
    'presenze.confermaTuttiSempre': (n, giorni, bloccati) => `Marquer ${n} ${n < 2 ? 'personne' : 'personnes'} au déjeuner et au dîner pendant ${giorni} ${giorni < 2 ? 'jour' : 'jours'} du camp ?`
      + (bloccati ? `\n\n${bloccati} ${bloccati < 2 ? 'jour est bloqué et reste' : 'jours sont bloqués et restent'} comme avant.` : '')
      + "\n\nÇa n'enlève rien : qui est déjà marqué reste comme il est. Ça change les présences aussi sur les autres téléphones.",
    'presenze.senzaDate': "Le camp n'a pas encore de dates : elles se choisissent dans « Le camp ».",
    'presenze.tuttiBloccati': 'Tous les jours du camp sont bloqués : les présences ne changent pas.',
    'presenze.bloccoNota': "Note tout le monde, puis enlève les quelques absents. Si tout le monde est déjà noté, le bouton les enlève tous. Chacun de ces boutons demande confirmation : il change les présences de tout le monde, sur tous les téléphones.",
