    'spesa.cibo': 'Dépense nourriture',
    'spesa.bevande': 'Dépense boissons',
    'spesa.logisticaEAttrezzatura': 'Logistique et matériel',
    'spesa.diCuiSeparato': 'dont sur le compte à part',
    'spesa.importoComplessivo': 'Montant total :',
    'spesa.contoDellaServa': 'Le compte de la bonne',
    'spesa.quotaPasto': 'Part par repas',
    'spesa.quotaPastoNota': (soldi, pasti, soloComuni) => `Nourriture+boissons (${soldi} €) / ${pasti} repas de ceux qui paient${soloComuni ? ' les jours communs' : ''}.`,
    'spesa.quotaPersona': 'Part par personne',
    'spesa.quotaPersonaNota': (soldi, n) => `Logistique et matériel (${soldi} €) / ${n} ${n < 2 ? 'personne' : 'personnes'} qui paient les jours communs.`,
    'spesa.logisticaTesta': 'Logistique par tête',
    'spesa.logisticaTestaNota': (soldi, n) => `Logistique (${soldi} €) / ${n} personnes qui paient les jours communs.`,
    'spesa.attrezzaturaTesta': 'Matériel par tête',
    'spesa.attrezzaturaTestaNota': (soldi, n) => `Matériel (${soldi} €) / ${n} ${n < 2 ? 'personne non exemptée' : 'personnes non exemptées'}.`,
    'spesa.separatoQuotaPasto': 'Compte à part — part par repas',
    'spesa.separatoQuotaNota': (soldi, pasti, giorni, persone) => `Nourriture+boissons à part (${soldi} €) / ${pasti} repas de ceux qui paient sur ${giorni} ${giorni < 2 ? 'jour' : 'jours'}, ${persone} ${persone < 2 ? 'personne' : 'personnes'}.`,
    'spesa.bambiniGratis': "Qui est exempté des dépenses ne paie pas : sa part est répartie sur les autres.",
    'quote.senzaPasti': (soldi) => `*Attention :* il y a des dépenses pour ${soldi} € mais aucun repas enregistré. Les parts restent à zéro tant que tu ne notes pas les présences dans l'onglet *Présences*.`,
    'quote.giorniGratis': (giorni, pasti) => `🎁 *${giorni} ${giorni < 2 ? 'journée offerte' : 'journées offertes'}* : ${pasti} ${pasti < 2 ? 'repas est exclu' : 'repas sont exclus'} des comptes. Ils restent notés au calendrier pour la cuisine, mais personne ne les paie — c'est pour ça que les repas comptés ci-dessous peuvent être moins nombreux que ceux que tu vois dans Présences.`,
    'quote.cassaComune': 'Parts de la caisse commune',
    'quote.cassaComuneNota': 'Nourriture et boissons des jours de tout le monde, plus logistique et matériel.',
    'quote.tuttiSeparati': (soldi) => `*Attention :* tous les jours avec des présences sont cochés en compte à part, mais il y a ${soldi} € de nourriture et de boissons sur le compte commun. Déplace ces dépenses sur le compte à part, ou décoche les jours qui sont à tout le monde.`,
    'quote.cassaSeparata': 'Parts de la caisse à part',
    'quote.cassaSeparataNota': (giorni) => `Seulement la nourriture et les boissons des ${giorni} ${giorni < 2 ? 'jour coché' : 'jours cochés'} dans le Calendrier, à la charge de qui était là.`,
    'quote.separataVuota': "Personne n'a de repas les jours cochés : il n'y a rien à partager ici.",
    'quote.separataSenzaPasti': (soldi) => `*Attention :* il y a ${soldi} € sur le compte à part mais aucun repas les jours cochés. Coche les jours dans* Calendrier* et note les* Présences*, sinon cette dépense n'entre pas dans les parts.`,
    'quote.totaleAPersona': 'Total par personne',
    'quote.totaleNota': "Les deux caisses additionnées : c'est ce que chacun sort en tout.",
    'quote.bambino': 'exempté',
    'quote.comunePiuSeparata': (comune, separata) => `${comune} € commun + ${separata} € à part`,
    'quote.gratis': 'Gratuit',
    'quote.totaleRaccolto': 'Total récolté',
    'saldi.tornaPerCassa': '↩ Revenir aux soldes par caisse',
    'saldi.ottimizza': (da, a) => `⚡ Optimiser les virements (${da} → ${a})`,
    'saldi.notaOttimizzati': "Tu vois les deux caisses mises ensemble. Pour comprendre d'où vient un chiffre, reviens aux soldes par caisse.",
    'saldi.notaPerCassa': "Réunit les deux caisses en une seule liste de virements : personne ne paie un centime de plus ou de moins, il y a juste moins de virements.",
    'saldi.passaggiOttimizzati': 'Virements optimisés',
    'saldi.passaggiNota': 'Les deux caisses ensemble. Les sommes dues sont les mêmes : seul change qui verse à qui, pour en faire moins. Les coches de cette vue sont séparées de celles par caisse.',
    'saldi.cassaComune': 'Soldes de la caisse commune',
    'saldi.finale': 'Solde final',
    'saldi.cassaComuneNota': 'Nourriture et boissons des jours de tout le monde, logistique et matériel.',
    'saldi.cassaSeparata': 'Soldes de la caisse à part',
    'saldi.cassaSeparataNota': (giorni) => `Seulement la nourriture et les boissons des ${giorni} ${giorni < 2 ? 'jour coché' : 'jours cochés'} : qui a avancé là est remboursé par qui était là.`,
    'saldi.separataVuota': 'Aucune avance et aucune part sur cette caisse.',
    'saldi.condividi': 'Partager le récapitulatif',
    'saldi.condividiNota': 'Prépare un message tout fait avec le total et le « qui paie qui » à envoyer dans le groupe.',
    'chiusura.contiTitolo': 'Clôture des comptes',
    'chiusura.chiusi': '🔒 Clos',
    'chiusura.contiChiusiNota': (quando) => `Comptes clos le *${quando}*. Les dépenses et le matériel sont gelés : les parts ne bougent plus, et le « qui paie qui » ne baisse qu'au fur et à mesure des remboursements. Ce qui arrive des autres téléphones est mis de côté et signalé ci-dessus.`,
    'chiusura.riapri': '🔓 Rouvrir les comptes',
    'chiusura.daFare': "À faire *quand les comptes sont définitifs et que les gens commencent à se payer*. Les remboursements déjà faits comptent de toute façon comme de l'argent payé, mais une dépense ajoutée après relance des virements : en clôturant, les dépenses et le matériel se figent et les présences encore ouvertes se bloquent.",
    'chiusura.chiudi': '🔒 Clore les comptes',
    'backup.titolo': 'Sauvegarde des données',
    'backup.nota': 'Chaque jour une copie de secours est enregistrée toute seule dans le nuage. Exporter/Importer sert à une sauvegarde manuelle dans un fichier.',
